class Company:
    def __init__(self, n):
        self.n = n
        self.bosses = [None] * (n + 1)
        self.signatures = {}

    def set_boss(self, x, y):
        self.bosses[x] = y

    def sign_document(self, x):
        current = x
        while current is not None:
            if current not in self.signatures:
                self.signatures[current] = set()
            self.signatures[current].add(x)
            current = self.bosses[current]

    def check_signature(self, x, i):
        return i in self.signatures.get(x, set())


def main():
    n, m = map(int, input().split())
    company = Company(n)

    for _ in range(m):
        event = list(map(int, input().split()))
        t = event[0]

        if t == 1:
            x, y = event[1], event[2]
            company.set_boss(x, y)
        elif t == 2:
            x = event[1]
            company.sign_document(x)
        elif t == 3:
            x, i = event[1], event[2]
            if company.check_signature(x, i):
                print("YES")
            else:
                print("NO")


if __name__ == "__main__":
    main()
